+
+    fn next(status: RunStatus, body: &EventBody) -> RunStatus {
+        match apply_lifecycle_event(status, body) {
+            LifecycleTransition::Next(next) => next,
+            other => panic!("expected Next, got {other:?} for {status} + {body:?}"),
