+
+    #[test]
+    fn request_start_resubmits_terminal_runs_to_submitted() {
+        let resume = EventBody::RunStartRequested(RunStartRequestedProps { resume: true });
+        assert_eq!(
+            next(
+                RunStatus::Failed {
+                    reason: FailureReason::WorkflowError,
+                },
