+    #[test]
+    fn runnable_pending_and_starting_advance_in_order() {
+        let pending = EventBody::RunPending(RunPendingProps {
+            reason: PendingReason::ApprovalRequired,
+        });
+        assert_eq!(next(RunStatus::Submitted, &pending), RunStatus::Pending {
+            reason: PendingReason::ApprovalRequired,
