+    #[test]
+    fn historic_skipped_statuses_replay_missing_intermediate_steps() {
+        // Historic submitted -> starting jumps skipped runnable.
+        assert_eq!(
+            historic_skipped_statuses(
+                RunStatus::Submitted,
+                &EventBody::RunStarting(transition_props()),
+            ),
+            vec![RunStatus::Runnable]
+        );
+        // Historic failure from submitted without runnable/starting events
+        // fast-forwards through both intermediate statuses.
+        assert_eq!(
+            historic_skipped_statuses(
+                RunStatus::Submitted,
+                &EventBody::RunFailed(failed(FailureReason::SandboxInitFailed)),
+            ),
+            vec![RunStatus::Runnable, RunStatus::Starting]
+        );
+        assert_eq!(
+            historic_skipped_statuses(
+                RunStatus::Runnable,
+                &EventBody::RunFailed(failed(FailureReason::SandboxInitFailed)),
+            ),
+            vec![RunStatus::Starting]
+        );
+        // Current-protocol streams skip nothing.
+        assert!(
+            historic_skipped_statuses(
+                RunStatus::Runnable,
+                &EventBody::RunStarting(transition_props()),
+            )
+            .is_empty()
+        );
+        assert!(
+            historic_skipped_statuses(
+                RunStatus::Running,
+                &EventBody::RunFailed(failed(FailureReason::WorkflowError)),
+            )
+            .is_empty()
+        );
+        // Failures the table accepts directly from submitted skip nothing.
+        assert!(
+            historic_skipped_statuses(
+                RunStatus::Submitted,
+                &EventBody::RunFailed(failed(FailureReason::Cancelled)),
+            )
+            .is_empty()
+        );
+    }
+
+    #[test]
+    fn idempotent_repeats_return_current_status() {
+        let running = EventBody::RunRunning(transition_props());
+        assert_eq!(
+            apply_lifecycle_event(RunStatus::Running, &running),
+            LifecycleTransition::Next(RunStatus::Running)
+        );
+        let removing = EventBody::RunRemoving(transition_props());
+        // Repeated removal is an idempotent no-op like every repeat.
+        assert_eq!(
+            apply_lifecycle_event(RunStatus::Removing, &removing),
+            LifecycleTransition::Next(RunStatus::Removing)
+        );
+    }
